def generate_good_numbers(limit):
    good_numbers = set()

    # Iterate over all pairs (x, y) such that 1 <= x < y and x^2 + y^2 <= limit
    x = 1
    while x * x * 2 < limit: # Optimization: x must be less than sqrt(limit/2)
        y_start = x + 1
        y_end = int((limit - x*x)**0.5)

        for y in range(y_start, y_end + 1):
            if math.gcd(x, y) > 1:
                m = x**2 + y**2
                good_numbers.add(m)
        x += 1

